1	#!/usr/bin/env python3
2	"""OpenSurvey HTTP service."""
3	import argparse
4	import json
5	import re
6	from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
7	from pathlib import Path
8	import signal
9	import sqlite3
10	import threading
11	from urllib.parse import urlsplit
12	
13	PRODUCT = "OpenSurvey"
14	RESOURCE = "surveys"
15	MAX_BODY_BYTES = 10 * 1024 * 1024
16	QUESTION_TYPES = ("text", "single_choice")
17	
18	PAGE = r"""<!doctype html>
19	<html lang="zh-CN">
20	<meta charset="utf-8">
21	<meta name="viewport" content="width=device-width,initial-scale=1">
22	<title>OpenSurvey · 问卷调查与反馈管理</title>
23	<style>
24	:root{--blue:#175b9c;--red:#c0392b;--grey:#666;--line:#d8dce3}
25	*{box-sizing:border-box}
26	body{font-family:system-ui,"PingFang SC","Microsoft YaHei",sans-serif;max-width:52rem;margin:2.5rem auto;padding:0 1rem;line-height:1.7;color:#1f2430}
27	a{color:var(--blue)}
28	h1{margin-bottom:.2rem}
29	h2{margin-top:2.2rem;border-bottom:1px solid var(--line);padding-bottom:.3rem}
30	.muted{color:var(--grey);font-size:.92rem}
31	ul.plain{list-style:none;padding-left:0}
32	ul.plain li{padding:.25rem 0;border-bottom:1px dashed var(--line)}
33	form label{display:block;margin:1rem 0 .25rem;font-weight:600}
34	input[type=text],textarea{width:100%;padding:.5rem .6rem;border:1px solid var(--line);border-radius:.35rem;font:inherit}
35	textarea{resize:vertical}
36	/* 标题与选项允许内部换行：用随内容增高的 textarea 展示，不能压成单行输入框 */
37	textarea.grow{resize:none;overflow:hidden;min-height:2.4rem;line-height:1.5}
38	.card{border:1px solid var(--line);border-radius:.5rem;padding:1rem 1.2rem;margin:1rem 0;background:#fafbfd}
39	.q-head{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;margin-bottom:.5rem}
40	.q-index{font-weight:700}
41	.tag{font-size:.8rem;background:#e8f0fa;color:var(--blue);border-radius:1rem;padding:.05rem .6rem}
42	.tag.required{background:#fdecea;color:var(--red)}
43	.req{margin:0;font-weight:400;display:flex;align-items:center;gap:.3rem}
44	.spacer{flex:1}
45	button{font:inherit;cursor:pointer}
46	.btn{border:1px solid var(--blue);background:var(--blue);color:#fff;border-radius:.35rem;padding:.45rem 1.1rem;text-decoration:none;display:inline-block}
47	.btn.secondary{background:#fff;color:var(--blue)}
48	.link{border:none;background:none;color:var(--blue);padding:0;font-size:.92rem}
49	.link.danger{color:var(--red)}
50	.row-actions{display:flex;gap:.8rem;flex-wrap:wrap;margin-top:1.2rem}
51	.opt-row{display:flex;align-items:center;gap:.6rem;margin:.4rem 0}
52	.opt-index{color:var(--grey);font-size:.9rem;min-width:3.2rem}
53	.banner{border:1px solid var(--red);background:#fdf3f2;color:var(--red);border-radius:.5rem;padding:.7rem 1rem;margin:1rem 0;white-space:normal}
54	.banner ul{margin:.4rem 0 0;padding-left:1.2rem}
55	.banner button{color:var(--red);text-decoration:underline;background:none;border:none;padding:0;text-align:left}
56	/* 保存状态条：与错误提示条区分开，明确“刚才那次提交已保存”与“还有未保存修改” */
57	.save-status{margin:1rem 0;display:flex;flex-direction:column;gap:.5rem}
58	.save-status[hidden]{display:none}
59	.save-note{border-radius:.5rem;padding:.7rem 1rem;white-space:normal}
60	.save-note.saved{border:1px solid #1e7e45;background:#ecf7f0;color:#155c33}
61	.save-note.dirty{border:1px solid #9a6d12;background:#fdf6e3;color:#7a5207}
62	/* 等待保存结果：蓝色中性提示，与成功（绿）、未保存（黄）、错误（红）区分 */
63	.save-note.saving{border:1px solid var(--blue);background:#eef4fb;color:#144a80}
64	button:disabled{opacity:.55;cursor:not-allowed}
65	.field-err{color:var(--red);font-size:.85rem;margin:.25rem 0 0;min-height:1px}
66	.invalid{border-color:var(--red)!important;background:#fdf6f5}
67	.detail-meta{color:var(--grey);font-size:.9rem}
68	.detail-desc,.opt-text-display{white-space:pre-wrap}
69	/* 标题中被接口保留的内部换行在列表与详情中也要原样显示 */
70	h2,.q-list .q-line,ul.plain a{white-space:pre-wrap}
71	.q-list>li{margin:1rem 0}
72	.q-list .q-line{font-weight:600}
73	.q-list ol{margin:.4rem 0 0 1.4rem}
74	</style>
75	<main>
76	<h1>OpenSurvey</h1>
77	<p>问卷调查与反馈管理</p>
78	<div id="app"></div>
79	<p class="muted"><a href="/api/surveys">问卷列表接口</a> · <a href="/health">服务状态</a></p>
80	</main>
81	<script>
82	"use strict";
83	const app = document.getElementById("app");
84	
85	// 每次进入一个页面都开启新一代视图：切换首页/详情/编辑、重新进入同一份问卷、
86	// 重试加载以及浏览器前进/后退都会使代数递增。较早一代页面发起的请求再晚
87	// 返回也必须丢弃，不能覆盖用户当前所在页面。
88	let activeView = 0;
89	
90	// 首尾裁剪必须与接口（Python str.strip()）逐字符一致，网页校验、提交内容与
91	// “是否还有未保存修改”的比较才能表达同一份文本含义。JS 原生 trim() 的字符集
92	// 恰好不同：它会裁掉 U+FEFF（接口保留该字符），却不裁 U+0085 与 U+001C–
93	// U+001F（接口会把它们当空白裁掉）。这里显式列出接口会裁的 29 个字符，
94	// U+FEFF 刻意不在其中；内部字符（含内部换行）一律不动。说明字段从不裁剪。
95	const API_TRIM_CLASS =
96	  "\\t\\n\\v\\f\\r\\x1c-\\x1f\\x20\\u0085\\u00a0\\u1680" +
97	  "\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000";
98	const apiTrimRe = new RegExp(
99	  "^[" + API_TRIM_CLASS + "]+|[" + API_TRIM_CLASS + "]+$", "g");
100	function apiTrim(value) { return value.replace(apiTrimRe, ""); }
101	
102	function h(tag, attrs, ...children) {
103	  const el = document.createElement(tag);
104	  if (attrs) for (const [k, v] of Object.entries(attrs)) {
105	    if (v === null || v === undefined) continue;
106	    if (k === "class") el.className = v;
107	    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
108	    else el.setAttribute(k, v);
109	  }
110	  for (const child of children.flat()) {
111	    if (child === null || child === undefined) continue;
112	    el.append(child.nodeType ? child : document.createTextNode(String(child)));
113	  }
114	  return el;
115	}
116	
117	/* ---------- 问卷表单（新建 / 编辑共用） ---------- */
118	
119	function buildSurveyForm(existing, hooks, view) {
120	  const mode = existing ? "edit" : "create";
121	
122	  const banner = h("div", {class: "banner", id: "form-banner"});
123	  banner.hidden = true;
124	
125	  // 编辑模式下保存结果的状态条：成功保存与“仍有未保存修改”必须分开展示，
126	  // 不能只给一条笼统的“保存成功”。新建模式不使用它（保存成功即进入详情）。
127	  const statusBar = h("div", {class: "save-status", id: "save-status", role: "status"});
128	  statusBar.hidden = true;
129	
130	  const titleInput = h("textarea", {id: "survey-title", rows: "1", class: "grow",
131	    maxlength: "200", placeholder: "请输入问卷标题（可含换行）"});
132	  const titleErr = h("p", {class: "field-err", id: "title-err"});
133	  const descArea = h("textarea", {id: "survey-desc", rows: "4", placeholder: "问卷说明（可留空，支持中文、引号与换行）"});
134	  const qBox = h("div", {id: "questions"});
135	  const qErr = h("p", {class: "field-err", id: "questions-err"});
136	
137	  function renumber() {
138	    const cards = qBox.querySelectorAll(".q-card");
139	    cards.forEach((card, i) => {
140	      card.querySelector(".q-index").textContent = `第 ${i + 1} 题`;
141	      card.querySelectorAll(".opt-row").forEach((row, j) => {
142	        row.querySelector(".opt-index").textContent = `选项 ${j + 1}`;
143	      });
144	    });
145	  }
146	
147	  // textarea 的高度随内容变化：单行内容外观与原输入框一致，出现内部换行时
148	  // 自动增高，让换行真实可见、可编辑，而不是被折叠或截断。
149	  function autoGrow(el) {
150	    el.style.height = "auto";
151	    el.style.height = `${el.scrollHeight}px`;
152	  }
153	  // 预填值时元素可能还没挂到文档上（scrollHeight 为 0），延到下一帧布局后再量。
154	  function scheduleGrow(el) { requestAnimationFrame(() => autoGrow(el)); }
155	
156	  function optionRow(value) {
157	    const text = h("textarea", {rows: "1", class: "opt-text grow", placeholder: "选项内容（可含换行）"});
158	    text.addEventListener("input", () => autoGrow(text));
159	    if (value !== undefined && value !== null) { text.value = value; scheduleGrow(text); }
160	    const row = h("div", {class: "opt-row"},
161	      h("span", {class: "opt-index"}, "选项"),
162	      text,
163	      h("button", {type: "button", class: "link danger", onclick: () => { row.remove(); renumber(); }}, "删除")
164	    );
165	    return row;
166	  }
167	
168	  function addQuestion(type, prefill) {
169	    const isChoice = type === "single_choice";
170	    const options = h("div", {class: "options"});
171	    const card = h("div", {class: "card q-card", "data-type": type},
172	      h("div", {class: "q-head"},
173	        h("span", {class: "q-index"}, "第 N 题"),
174	        h("span", {class: "tag q-type-tag"}, isChoice ? "单选题" : "文本题"),
175	        h("label", {class: "req"},
176	          h("input", {type: "checkbox", class: "q-required"}), "必填（默认非必填）"),
177	        h("span", {class: "spacer"}),
178	        h("button", {type: "button", class: "link danger", onclick: () => { card.remove(); renumber(); }}, "删除本题")
179	      ),
180	      h("textarea", {rows: "1", class: "q-title grow", placeholder: "题目标题（可含换行）"}),
181	      h("p", {class: "field-err q-title-err"})
182	    );
183	    if (isChoice) {
184	      const saved = prefill && Array.isArray(prefill.options) ? prefill.options : null;
185	      if (saved && saved.length) saved.forEach(value => options.append(optionRow(value)));
186	      else options.append(optionRow(), optionRow());
187	      card.append(
188	        options,
189	        h("p", {class: "field-err opt-err"}),
190	        h("button", {type: "button", class: "link add-opt"}, "添加选项")
191	      );
192	      card.querySelector(".add-opt").addEventListener("click", () => {
193	        options.append(optionRow());
194	        renumber();
195	        options.querySelector(".opt-row:last-child .opt-text").focus();
196	      });
197	    }
198	    const qTitleEl = card.querySelector(".q-title");
199	    qTitleEl.addEventListener("input", () => autoGrow(qTitleEl));
200	    if (prefill) {
201	      qTitleEl.value = prefill.title != null ? prefill.title : "";
202	      card.querySelector(".q-required").checked = !!prefill.required;
203	    }
204	    scheduleGrow(qTitleEl);
205	    qBox.append(card);
206	    renumber();
207	    if (!prefill) qTitleEl.focus();
208	    return card;
209	  }
210	
211	  function clearErrors() {
212	    banner.hidden = true;
213	    banner.replaceChildren();
214	    titleErr.textContent = "";
215	    qErr.textContent = "";
216	    qBox.querySelectorAll(".invalid").forEach(el => el.classList.remove("invalid"));
217	    qBox.querySelectorAll(".field-err").forEach(el => { el.textContent = ""; });
218	  }
219	
220	  function hideSaveStatus() {
221	    statusBar.hidden = true;
222	    statusBar.replaceChildren();
223	  }
224	
225	  // 保存成功后：绿色块只陈述“刚才提交的内容已保存”；若等待期间又有修改，
226	  // 再追加一块黄色“当前还有未保存的修改”。两者同时出现、含义互不混淆。
227	  function renderSaveStatus(dirty) {
228	    statusBar.replaceChildren(
229	      h("div", {class: "save-note saved", id: "save-note-saved"},
230	        h("strong", null, "已保存：刚才提交的内容已保存到服务器。")),
231	      dirty
232	        ? h("div", {class: "save-note dirty", id: "save-note-dirty"},
233	            h("strong", null,
234	              "当前还有未保存的修改：页面内容在点击保存后又被改动（等待结果期间的修改不会自动补交）。可继续编辑，并再次点击“保存修改”。"))
235	        : null
236	    );
237	    statusBar.hidden = false;
238	  }
239	
240	  // 一次保存进行中：保存按钮禁用并明确显示“正在保存…”，状态条显示等待提示。
241	  // 在请求有明确结果前，重复点击按钮或用键盘再次提交都不会追加请求，也不会
242	  // 清掉等待提示。等待期间标题、说明、题目、选项、必填与增删操作全部可用。
243	  let saving = false;
244	  function setSavingUI() {
245	    submitButton.disabled = true;
246	    submitButton.textContent = "正在保存…";
247	    statusBar.replaceChildren(
248	      h("div", {class: "save-note saving", id: "save-note-saving", role: "status"},
249	        h("strong", null, "正在保存：正在等待本次保存的结果，请稍候。等待期间仍可继续编辑，这些改动不会自动追加到本次提交。"))
250	    );
251	    statusBar.hidden = false;
252	  }
253	  function resetSaveButton() {
254	    submitButton.disabled = false;
255	    submitButton.textContent = submitButton.getAttribute("data-label");
256	  }
257	
258	  // 整份草稿的唯一整理入口：保存时提交的内容、保存前的校验、编辑页判断
259	  // “等待保存期间是否又有修改”都从这里取数，规则只维护这一份。标题/题目
260	  // 标题/选项只按接口规则（apiTrim，与 Python strip 一致）去掉首尾空白，
261	  // 说明与内部换行原样保留；题目与选项按页面当前顺序记录，必填勾选原样。
262	  // 每次调用都返回新建的独立对象（后续输入不会改变已返回的快照），可直接
263	  // 做整体相等比较：改过又恢复原值时结构相同，不会被当成有未保存修改。
264	  function readDraft() {
265	    return {
266	      title: apiTrim(titleInput.value),
267	      description: descArea.value,
268	      questions: [...qBox.querySelectorAll(".q-card")].map(card => ({
269	        type: card.dataset.type,
270	        title: apiTrim(card.querySelector(".q-title").value),
271	        required: card.querySelector(".q-required").checked,
272	        options: [...card.querySelectorAll(".opt-text")].map(el => apiTrim(el.value))
273	      }))
274	    };
275	  }
276	
277	  function sameState(a, b) { return JSON.stringify(a) === JSON.stringify(b); }
278	
279	  function showBanner(items) {
280	    banner.replaceChildren(h("strong", null, "问卷未能保存，请修改后重试："), h("ul", null,
281	      items.map(it => h("li", null, h("button", {type: "button", onclick: () => it.el && it.el.focus()}, it.msg)))));
282	    banner.hidden = false;
283	    banner.scrollIntoView({behavior: "smooth", block: "nearest"});
284	  }
285	
286	  const actionButtons = [
287	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("text")}, "添加文本题"),
288	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("single_choice")}, "添加单选题"),
289	    h("span", {class: "spacer"})
290	  ];
291	  if (mode === "edit") {
292	    // 离开编辑页即丢弃全部未保存的增删与输入
293	    actionButtons.push(h("a", {class: "btn secondary", href: `#/surveys/${existing.id}`}, "取消"));
294	  }
295	  const submitLabel = mode === "edit" ? "保存修改" : "保存整份问卷";
296	  const submitButton = h("button", {type: "submit", class: "btn", "data-label": submitLabel}, submitLabel);
297	  actionButtons.push(submitButton);
298	
299	  const form = h("form", {id: "draft-form", onsubmit: submitForm},
300	    banner,
301	    statusBar,
302	    h("section", null,
303	      h("h2", null, mode === "edit" ? `编辑问卷草稿 #${existing.id}` : "新建问卷草稿"),
304	      mode === "edit"
305	        ? h("p", {class: "muted"}, "保存将整份替换当前草稿；取消则放弃本次修改，问卷编号和地址不变。")
306	        : null,
307	      h("label", {for: "survey-title"}, "标题"),
308	      titleInput, titleErr,
309	      h("label", {for: "survey-desc"}, "说明"),
310	      descArea,
311	      h("label", null, "题目（按下方顺序保存，至少保留一道题）"),
312	      qBox, qErr,
313	      h("div", {class: "row-actions"}, actionButtons)
314	    )
315	  );
316	
317	  titleInput.addEventListener("input", () => autoGrow(titleInput));
318	  if (mode === "edit") {
319	    titleInput.value = existing.title != null ? existing.title : "";
320	    descArea.value = existing.description || "";
321	    existing.questions.forEach(question => addQuestion(question.type, question));
322	    renumber();
323	    scheduleGrow(titleInput);
324	
325	    // 最近一次服务器确认保存的表单内容（点击保存时的快照）。它只用于成功返回
326	    // 后判断当前表单相对那次提交有没有新改动；等待期间的输入始终留在表单里，
327	    // 不会被它覆盖，也不会被自动补交。
328	    let savedState = readDraft();
329	
330	    function refreshDirty() {
331	      const dirtyNote = statusBar.querySelector("#save-note-dirty");
332	      // 尚未成功保存过（状态条隐藏）时无需提示。
333	      if (statusBar.hidden || !dirtyNote) return;
334	      // 与点击保存时的整份内容比较：改过又恢复原值即视为无未保存修改。
335	      dirtyNote.hidden = sameState(readDraft(), savedState);
336	    }
337	
338	    // 监听编辑页上全部真实编辑动作（标题/说明/题目标题/选项输入、必填勾选、
339	    // 题目与选项增删）。题目卡片是动态增删的，因此在表单上做事件委托。
340	    form.addEventListener("input", refreshDirty);
341	    form.addEventListener("change", event => {
342	      if (event.target.closest && event.target.closest(".q-required")) refreshDirty();
343	    });
344	    form.addEventListener("click", event => {
345	      const actionable = event.target.closest
346	        && event.target.closest("button.add-opt, button.link.danger, button.btn.secondary");
347	      if (actionable) {
348	        // 新增/删除在本次点击处理中完成，延到冒泡后再读取最终 DOM。
349	        queueMicrotask(refreshDirty);
350	      }
351	    });
352	
353	    hooks = hooks || {};
354	    hooks.markSaved = state => { savedState = state; };
355	    hooks.isCurrent = state => sameState(readDraft(), state);
356	  }
357	
358	  async function submitForm(event) {
359	    event.preventDefault();
360	    // 已有一次保存尚未得到明确结果：忽略后续点击/键盘提交，不追加请求，也不
361	    // 清除正在显示的等待状态。本次保存只代表首次点击时的那份表单快照。
362	    if (saving) return;
363	    clearErrors();
364	    hideSaveStatus();
365	    const problems = [];
366	
367	    // 点击保存这一刻的整份草稿：整理规则只有 readDraft 一处，校验、提交内容
368	    // 与成功后的“是否有新修改”比较表达的都是同一份草稿。
369	    const draft = readDraft();
370	
371	    if (!draft.title) {
372	      titleInput.classList.add("invalid");
373	      titleErr.textContent = "标题不能为空。";
374	      problems.push({el: titleInput, msg: "问卷标题不能为空。"});
375	    }
376	
377	    const cards = [...qBox.querySelectorAll(".q-card")];
378	    if (cards.length === 0) {
379	      qErr.textContent = "问卷至少需要保留一道题。";
380	      problems.push({el: qBox, msg: "问卷至少需要保留一道题，请先添加题目。"});
381	    }
382	
383	    // 校验针对整理后的草稿内容（空标题、空选项、同题重复选项都按裁剪后的值
384	    // 判断），错误标记仍落在对应的页面输入框上；输入框原文保持不动。
385	    cards.forEach((card, i) => {
386	      const loc = `第 ${i + 1} 题`;
387	      const question = draft.questions[i];
388	      const titleEl = card.querySelector(".q-title");
389	      if (!question.title) {
390	        titleEl.classList.add("invalid");
391	        card.querySelector(".q-title-err").textContent = `${loc}：题目标题不能为空。`;
392	        problems.push({el: titleEl, msg: `${loc}：题目标题不能为空。`});
393	      }
394	      if (question.type === "single_choice") {
395	        const optInputs = [...card.querySelectorAll(".opt-text")];
396	        const optErr = card.querySelector(".opt-err");
397	        const seen = new Set();
398	        question.options.forEach((val, j) => {
399	          if (!val) {
400	            optInputs[j].classList.add("invalid");
401	            optErr.textContent = `${loc}：第 ${j + 1} 个选项不能为空。`;
402	            problems.push({el: optInputs[j], msg: `${loc}：第 ${j + 1} 个选项不能为空。`});
403	          } else if (seen.has(val)) {
404	            optInputs[j].classList.add("invalid");
405	            optErr.textContent = `${loc}：选项“${val}”与同题其他选项重复。`;
406	            problems.push({el: optInputs[j], msg: `${loc}：选项“${val}”重复。`});
407	          }
408	          seen.add(val);
409	        });
410	        if (question.options.length < 2) {
411	          optErr.textContent = `${loc}：单选题至少需要两个选项。`;
412	          problems.push({el: card.querySelector(".add-opt"), msg: `${loc}：单选题至少需要两个选项。`});
413	        }
414	      }
415	    });
416	
417	    if (problems.length) {
418	      showBanner(problems);
419	      return;
420	    }
421	    // 校验通过、请求即将发出：此后到拿到明确结果前只能有这一次保存进行中。
422	    // 纯客户端校验拒绝不会走到这里，因此不会留下等待状态。
423	    saving = true;
424	    setSavingUI();
425	
426	    // 提交内容就是这份草稿本身：文本题不带 options（接口接受省略或空数组），
427	    // 单选题按整理后的选项内容与顺序提交。
428	    const payload = {
429	      title: draft.title,
430	      description: draft.description,
431	      questions: draft.questions.map(q => q.type === "single_choice"
432	        ? {type: q.type, title: q.title, required: q.required, options: q.options}
433	        : {type: q.type, title: q.title, required: q.required})
434	    };
435	    // 点击保存这一刻的整份表单快照：这次请求只代表这份内容。readDraft 返回的
436	    // 是独立对象，等待期间的后续输入不会改变它；成功返回后拿它与重新读取的
437	    // 当前表单比较——等待期间的任何输入/增删都不属于本次保存。
438	    const submittedState = draft;
439	    const endpoint = mode === "edit" ? `/api/surveys/${existing.id}` : "/api/surveys";
440	    // 这次保存只属于发起它的那一代表单；响应再晚返回，只要用户已经离开
441	    // （首页/详情/编辑切换、重新进入同一问卷、浏览器前进后退），其成功或
442	    // 失败结果都必须静默丢弃，不能跳转、清空或提示到当前页面上。
443	    const submitView = view;
444	    let resp;
445	    try {
446	      resp = await fetch(endpoint, {
447	        method: mode === "edit" ? "PUT" : "POST",
448	        headers: {"Content-Type": "application/json"},
449	        body: JSON.stringify(payload)
450	      });
451	    } catch (err) {
452	      if (submitView !== activeView) return;
453	      // 请求未成功：结束等待，保留当前全部输入与增删结果，允许修改后再次保存。
454	      saving = false;
455	      resetSaveButton();
456	      hideSaveStatus();
457	      showBanner([{el: null, msg: `网络错误，问卷尚未保存：${err}`}]);
458	      return;
459	    }
460	    if (submitView !== activeView) return;
461	    let data = {};
462	    try { data = await resp.json(); } catch (_) { /* 保留已输入内容 */ }
463	    if (submitView !== activeView) return;
464	    const saved = mode === "edit" ? resp.status === 200 : resp.status === 201;
465	    if (saved && data.id !== undefined) {
466	      if (mode === "create") {
467	        form.reset();
468	        qBox.replaceChildren();
469	        autoGrow(titleInput);
470	        if (hooks && hooks.onCreated) hooks.onCreated();
471	        location.hash = `#/surveys/${data.id}`;
472	        return;
473	      }
474	      // 编辑模式：先把“这次提交的内容”记为已保存（服务器上的草稿正是它）。
475	      if (hooks && hooks.markSaved) hooks.markSaved(submittedState);
476	      // 比较点击保存前后的整份表单：等待期间改过又恢复原值时结构相同，按
477	      // 无新改动处理，仍进入详情。
478	      const stillSame = hooks && hooks.isCurrent ? hooks.isCurrent(submittedState) : true;
479	      if (stillSame) {
480	        location.hash = `#/surveys/${data.id}`;
481	        return;
482	      }
483	      // 等待期间出现了新的修改：留在编辑页，保留当前完整内容与顺序。绿色块
484	      // 只确认“刚才提交的内容已保存”，黄色块提示“当前还有未保存的修改”，
485	      // 不自动补交，也不撤销已成功的保存。保存恢复可用，再次点击提交的才是
486	      // 当前内容，而不是沿用上一笔提交的旧内容。
487	      saving = false;
488	      resetSaveButton();
489	      renderSaveStatus(true);
490	      return;
491	    }
492	    // 服务端未确认保存成功：结束等待，不清空任何输入，展示具体问题；用户修改
493	    // 后可再次保存（不会自行重发，也不会一直停在“正在保存”）。
494	    saving = false;
495	    resetSaveButton();
496	    hideSaveStatus();
497	    showBanner([{el: null, msg: data.error || `保存失败（HTTP ${resp.status}），问卷未保存，请检查后重试。`}]);
498	  }
499	
500	  return form;
501	}
