673	def validate_survey(obj):
674	    """Validate a decoded survey payload.
675	
676	    Returns (clean_survey, None) on success or (None, error_message) on failure.
677	    Strings are stored trimmed of surrounding whitespace; description keeps its
678	    raw value so Chinese, quotes and newlines are preserved.
679	    """
680	    if not isinstance(obj, dict):
681	        return None, "请求体必须是 JSON 对象"
682	    if "title" not in obj:
683	        return None, "缺少字段 title"
684	    title = obj["title"]
685	    if not isinstance(title, str):
686	        return None, "title 必须是字符串"
687	    title = title.strip()
688	    if not title:
689	        return None, "title 不能为空（或全为空白字符）"
690	
691	    description = obj.get("description", "")
692	    if not isinstance(description, str):
693	        return None, "description 必须是字符串"
694	
695	    if "questions" not in obj:
696	        return None, "缺少字段 questions"
697	    raw_questions = obj["questions"]
698	    if not isinstance(raw_questions, list):
699	        return None, "questions 必须是数组"
700	    if len(raw_questions) == 0:
701	        return None, "questions 至少需要一道题"
702	
703	    questions = []
704	    for index, raw_question in enumerate(raw_questions, start=1):
705	        location = f"第 {index} 题"
706	        if not isinstance(raw_question, dict):
707	            return None, f"{location}（questions[{index - 1}]）必须是对象"
708	
709	        if "type" not in raw_question:
710	            return None, f"{location}：缺少字段 type"
711	        question_type = raw_question["type"]
712	        if not isinstance(question_type, str):
713	            return None, f"{location}：type 必须是字符串"
714	        if question_type not in QUESTION_TYPES:
715	            shown = json.dumps(question_type, ensure_ascii=False)
716	            return None, f"{location}：不支持的题型 {shown}（仅支持 text 或 single_choice）"
717	
718	        if "title" not in raw_question:
719	            return None, f"{location}：缺少字段 title"
720	        question_title = raw_question["title"]
721	        if not isinstance(question_title, str):
722	            return None, f"{location}：title 必须是字符串"
723	        question_title = question_title.strip()
724	        if not question_title:
725	            return None, f"{location}：题目标题不能为空（或全为空白字符）"
726	
727	        required = raw_question.get("required", False)
728	        if not isinstance(required, bool):
729	            return None, f"{location}：required 必须是布尔值"
730	
731	        raw_options = raw_question.get("options", [])
732	        if not isinstance(raw_options, list):
733	            return None, f"{location}：options 必须是数组"
734	
735	        options = []
736	        if question_type == "text":
737	            if len(raw_options) > 0:
738	                return None, f"{location}：文本题不能包含选项（options 必须省略或为空数组）"
739	        else:
740	            if len(raw_options) < 2:
741	                return None, f"{location}：单选题至少需要两个选项"
742	            seen = set()
743	            for option_index, raw_option in enumerate(raw_options, start=1):
744	                if not isinstance(raw_option, str):
745	                    return None, f"{location}：第 {option_index} 个选项必须是字符串"
746	                option = raw_option.strip()
747	                if not option:
748	                    return None, f"{location}：第 {option_index} 个选项不能为空（或全为空白字符）"
749	                if option in seen:
750	                    shown = json.dumps(option, ensure_ascii=False)
751	                    return None, f"{location}：选项 {shown} 重复（同一题内选项不得重复）"
752	                seen.add(option)
753	                options.append(option)
754	
755	        questions.append({
756	            "type": question_type,
757	            "title": question_title,
758	            "required": required,
759	            "options": options,
760	        })
761	
762	    return {
763	        "title": title,
764	        "description": description,
765	        "questions": questions,
766	    }, None
767	
