769	def main():
770	    parser = argparse.ArgumentParser(description="OpenSurvey - 问卷调查与反馈管理")
771	    commands = parser.add_subparsers(dest="command", required=True)
772	    serve = commands.add_parser("serve", help="Start the HTTP service")
773	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
774	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
775	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
776	    args = parser.parse_args()
777	    if not 0 <= args.port <= 65535:
778	        parser.error("port must be between 0 and 65535")
779	    args.data_dir.mkdir(parents=True, exist_ok=True)
780	    # 每个连接由独立线程处理（见下方 ThreadingHTTPServer），因此数据库连接
781	    # 会被多个线程共享：check_same_thread=False 允许跨线程使用，所有读写再
782	    # 经 db_lock 串行化，保证一次保存/替换内部的多条语句仍然原子生效。
783	    database = sqlite3.connect(args.data_dir / "open-survey.sqlite", check_same_thread=False)
784	    db_lock = threading.Lock()
785	    database.execute("CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY, title TEXT NOT NULL)")
786	    columns = {row[1] for row in database.execute("PRAGMA table_info(surveys)")}
787	    if "description" not in columns:
788	        database.execute("ALTER TABLE surveys ADD COLUMN description TEXT NOT NULL DEFAULT ''")
789	    database.execute(
790	        "CREATE TABLE IF NOT EXISTS questions ("
791	        "id INTEGER PRIMARY KEY, survey_id INTEGER NOT NULL, position INTEGER NOT NULL, "
792	        "type TEXT NOT NULL, title TEXT NOT NULL, required INTEGER NOT NULL)"
793	    )
794	    database.execute(
795	        "CREATE TABLE IF NOT EXISTS question_options ("
796	        "id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL)"
797	    )
798	    database.commit()
799	
800	    def survey_detail(survey_id):
801	        with db_lock:
802	            row = database.execute(
803	                "SELECT title, COALESCE(description, '') FROM surveys WHERE id = ?",
804	                (survey_id,),
805	            ).fetchone()
806	            if row is None:
807	                return None
808	            title, description = row
809	            questions = []
810	            question_rows = database.execute(
811	                "SELECT id, type, title, required FROM questions WHERE survey_id = ? ORDER BY position",
812	                (survey_id,),
813	            ).fetchall()
814	            for question_id, question_type, question_title, required in question_rows:
815	                options = [option_row[0] for option_row in database.execute(
816	                    "SELECT text FROM question_options WHERE question_id = ? ORDER BY position",
817	                    (question_id,),
818	                )]
819	                questions.append({
820	                    "type": question_type,
821	                    "title": question_title,
822	                    "required": bool(required),
823	                    "options": options,
824	                })
825	        return {
826	            "id": survey_id,
827	            "title": title,
828	            "description": description,
829	            "questions": questions,
830	        }
831	
832	    def save_survey(clean):
833	        """Insert the whole survey atomically; returns the new id."""
834	        with db_lock:
835	            try:
836	                cursor = database.execute(
837	                    "INSERT INTO surveys (title, description) VALUES (?, ?)",
838	                    (clean["title"], clean["description"]),
839	                )
840	                survey_id = cursor.lastrowid
841	                write_questions(survey_id, clean["questions"])
842	                database.commit()
843	                return survey_id
844	            except Exception:
845	                database.rollback()
846	                raise
847	
848	    def write_questions(survey_id, questions):
849	        """Replace all questions/options of a survey with the given ordered list."""
850	        old_question_ids = [row[0] for row in database.execute(
851	            "SELECT id FROM questions WHERE survey_id = ?", (survey_id,)
852	        )]
853	        if old_question_ids:
854	            placeholders = ",".join("?" for _ in old_question_ids)
855	            database.execute(
856	                f"DELETE FROM question_options WHERE question_id IN ({placeholders})",
857	                old_question_ids,
858	            )
859	        database.execute("DELETE FROM questions WHERE survey_id = ?", (survey_id,))
860	        for position, question in enumerate(questions):
861	            question_cursor = database.execute(
862	                "INSERT INTO questions (survey_id, position, type, title, required) "
863	                "VALUES (?, ?, ?, ?, ?)",
864	                (survey_id, position, question["type"], question["title"],
865	                 1 if question["required"] else 0),
866	            )
867	            question_id = question_cursor.lastrowid
868	            for option_position, option in enumerate(question["options"]):
869	                database.execute(
870	                    "INSERT INTO question_options (question_id, position, text) VALUES (?, ?, ?)",
871	                    (question_id, option_position, option),
872	                )
873	
874	    def replace_survey(survey_id, clean):
875	        """Replace a whole survey atomically; keeps the same id.
876	
877	        Returns False when the survey does not exist (no record is created).
878	        """
879	        with db_lock:
880	            row = database.execute("SELECT 1 FROM surveys WHERE id = ?", (survey_id,)).fetchone()
881	            if row is None:
882	                return False
883	            try:
884	                database.execute(
885	                    "UPDATE surveys SET title = ?, description = ? WHERE id = ?",
886	                    (clean["title"], clean["description"], survey_id),
887	                )
888	                write_questions(survey_id, clean["questions"])
889	                database.commit()
890	                return True
891	            except Exception:
892	                database.rollback()
