895	    class Handler(BaseHTTPRequestHandler):
896	        def respond(self, status, value, *, html=False, allow=None):
897	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
898	            self.send_response(status)
899	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
900	            self.send_header("Content-Length", str(len(payload)))
901	            if status == 405 and allow is not None:
902	                self.send_header("Allow", ", ".join(allow))
