906	        def list_surveys(self):
907	            with db_lock:
908	                records = [
909	                    {"id": row[0], "title": row[1]}
910	                    for row in database.execute("SELECT id, title FROM surveys ORDER BY id")
911	                ]
912	            self.respond(200, {RESOURCE: records})
913	
914	        def read_payload(self):
915	            """Read and decode a JSON request body.
916	
917	            Returns (payload, None) or (None, error_message).
918	            """
919	            try:
920	                length = int(self.headers.get("Content-Length") or 0)
921	            except ValueError:
922	                length = -1
923	            if length < 0:
924	                return None, "Content-Length 无效"
925	            if length > MAX_BODY_BYTES:
926	                return None, "请求体过大"
927	            body = self.rfile.read(length) if length else b""
928	            try:
929	                return json.loads(body.decode("utf8")), None
930	            except (UnicodeDecodeError, json.JSONDecodeError) as error:
931	                return None, f"请求体不是合法 JSON：{error}"
