933	        def create_survey(self):
934	            payload, error = self.read_payload()
935	            if error is not None:
936	                self.respond(400, {"error": error})
937	                return
938	
939	            clean, error = validate_survey(payload)
940	            if error is not None:
941	                self.respond(400, {"error": error})
