953	            if survey_detail(survey_id) is None:
954	                # Editing a missing id is always 404 and must never create one.
955	                self.respond(404, {"error": "not found"})
956	                return
957	            if read_error is not None:
958	                self.respond(400, {"error": read_error})
959	                return
960	
961	            # Full replacement: validate before touching the stored draft so a
962	            # rejected request leaves the old survey exactly as it was.
963	            clean, error = validate_survey(payload)
964	            if error is not None:
