974	        def route(self):
975	            location = urlsplit(self.path).path
976	            detail_match = re.fullmatch(r"/api/surveys/(\d+)", location)
977	
978	            if location == "/api/surveys":
979	                allowed = ["GET", "POST"]
980	            elif location in ("/", "/health"):
