    # ---------- 加载失败：网络错误 ----------

    def test_network_error_shows_retry_and_back_without_form_or_data_change(self):
        """网络错误：明确提示加载失败、提供重试/返回详情，不进表单，草稿原样保留。"""
        survey_id, saved = self.standard_survey()
        before_list = self.survey_ids()

